+        if (!isSymbolicInstance(m)) return m;
+        GenericMethod gm = ((MethodInstance) m).getGenerator();
+        return (Method) EvaluatorBase.inferAndInstantiateGenericFunction(args, gm, gm.evaluationEnv);
+    }
